"""Docker emits one Boolean only. No Env values, names, or complete inspect object leave the daemon."""
FORBIDDEN=['APACHE_DISABLE_REWRITE_IP', 'APACHE_PID_FILE', 'FORWARDED_FOR_HEADERS', 'FRANKENPHP_WORKER', 'MAIL_DOMAIN', 'MAIL_FROM_ADDRESS', 'NEXTCLOUD_CONFIG_DIR', 'NEXTCLOUD_INIT_HTACCESS', 'OBJECTSTORE_S3_AUTOCREATE', 'OBJECTSTORE_S3_BUCKET', 'OBJECTSTORE_S3_HOST', 'OBJECTSTORE_S3_KEY', 'OBJECTSTORE_S3_KEY_FILE', 'OBJECTSTORE_S3_LEGACYAUTH', 'OBJECTSTORE_S3_OBJECT_PREFIX', 'OBJECTSTORE_S3_PORT', 'OBJECTSTORE_S3_REGION', 'OBJECTSTORE_S3_SECRET', 'OBJECTSTORE_S3_SECRET_FILE', 'OBJECTSTORE_S3_SSE_C_KEY', 'OBJECTSTORE_S3_SSE_C_KEY_FILE', 'OBJECTSTORE_S3_SSE_KMS_ENABLED', 'OBJECTSTORE_S3_SSE_KMS_KEY_ID', 'OBJECTSTORE_S3_SSL', 'OBJECTSTORE_S3_STORAGE_CLASS', 'OBJECTSTORE_S3_USEPATH_STYLE', 'OBJECTSTORE_SWIFT_AUTOCREATE', 'OBJECTSTORE_SWIFT_CONTAINER_NAME', 'OBJECTSTORE_SWIFT_PROJECT_DOMAIN', 'OBJECTSTORE_SWIFT_PROJECT_NAME', 'OBJECTSTORE_SWIFT_REGION', 'OBJECTSTORE_SWIFT_SERVICE_NAME', 'OBJECTSTORE_SWIFT_URL', 'OBJECTSTORE_SWIFT_USER_DOMAIN', 'OBJECTSTORE_SWIFT_USER_NAME', 'OBJECTSTORE_SWIFT_USER_PASSWORD', 'OVERWRITECLIURL', 'OVERWRITECONDADDR', 'OVERWRITEHOST', 'OVERWRITEPROTOCOL', 'OVERWRITEWEBROOT', 'PHP_INI_SCAN_DIR', 'REDIS_HOST', 'REDIS_HOST_PASSWORD', 'REDIS_HOST_PASSWORD_FILE', 'REDIS_HOST_PORT', 'REDIS_HOST_USER', 'REDIS_PROTOCOL', 'SMTP_AUTHTYPE', 'SMTP_HOST', 'SMTP_NAME', 'SMTP_PASSWORD', 'SMTP_PASSWORD_FILE', 'SMTP_PORT', 'SMTP_SECURE', 'TRUSTED_PROXIES']
DEFAULTS={'APACHE_CONFDIR':'/etc/apache2','APACHE_ENVVARS':'/etc/apache2/envvars','PHP_INI_DIR':'/usr/local/etc/php','PATH':'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','APACHE_RUN_USER':'www-data','APACHE_RUN_GROUP':'www-data','APACHE_RUN_DIR':'/var/run/apache2','APACHE_LOCK_DIR':'/var/lock/apache2','APACHE_LOG_DIR':'/var/log/apache2'}
def template():
 out='{{$ok := true}}{{$seenPath := false}}{{$seenConf := false}}{{$seenVars := false}}{{range .Config.Env}}{{$name := index (split . "=") 0}}'
 for name in FORBIDDEN:out+='{{if eq $name "'+name+'"}}{{$ok = false}}{{end}}'
 out+='{{if ge (len $name) 3}}{{if eq (slice $name 0 3) "NC_"}}{{$ok = false}}{{end}}{{end}}'
 for name,value in DEFAULTS.items():out+='{{if eq $name "'+name+'"}}{{if ne . "'+name+'='+value+'"}}{{$ok = false}}{{end}}{{end}}'
 out+='{{if eq $name "PATH"}}{{$seenPath = true}}{{end}}{{if eq $name "APACHE_CONFDIR"}}{{$seenConf = true}}{{end}}{{if eq $name "APACHE_ENVVARS"}}{{$seenVars = true}}{{end}}'
 return out+'{{end}}{{and $ok $seenPath $seenConf $seenVars}}'
